/**
 * Service profiles stores and serves user profile information.
 */
export namespace profiles {
    export interface LoginParams {
        "user_email": string
        password: string
    }

    /**
     * LoginResponse carries the session only in an HttpOnly cookie: the token is
     * never exposed to JavaScript.
     */
    export interface LoginResponse {
        "expires_at": string
    }

    export interface MemberTypeOption {
        name: string
        value: string
    }

    /**
     * PersonalData holds the personal details linked one-to-one to a user profile.
     */
    export interface PersonalData {
        "user_id": string
        "first_name": string
        "last_name": string
        address: string
        cap: string
        city: string
        country: string
        "created_at": string
        "updated_at": string
    }

    /**
     * PersonalDataParams are the editable fields of a user's personal data.
     */
    export interface PersonalDataParams {
        "first_name": string
        "last_name": string
        address: string
        cap: string
        city: string
        country: string
    }

    /**
     * PersonalSetup holds the broadcasting configuration linked to a user profile.
     */
    export interface PersonalSetup {
        "user_id": string
        "can_broadcast": boolean
        "room_name": string
    }

    export interface PersonalSetupParams {
        "can_broadcast": boolean
        "room_name": string
    }

    export interface Profile {
        "user_id": string
        email: string
        "display_name": string
        "avatar_url": string
        "member_type": string
        broadcaster: string
        role: string
        status: Status
        "created_at": string
        "updated_at": string
    }

    export interface ProfileParams {
        "display_name": string
        "avatar_url": string
    }

    export type Status = number

    /**
     * StatusOption describes a valid profile status for display in admin UIs.
     */
    export interface StatusOption {
        name: string
        value: Status
        updatable: boolean
    }

    export class ServiceClient {
        private baseClient: BaseClient

        constructor(baseClient: BaseClient) {
            this.baseClient = baseClient
            this.Delete = this.Delete.bind(this)
            this.Get = this.Get.bind(this)
            this.GetPersonalData = this.GetPersonalData.bind(this)
            this.GetPersonalSetup = this.GetPersonalSetup.bind(this)
            this.GetUserPersonalSetup = this.GetUserPersonalSetup.bind(this)
            this.Login = this.Login.bind(this)
            this.Me = this.Me.bind(this)
            this.Update = this.Update.bind(this)
            this.UploadAvatar = this.UploadAvatar.bind(this)
            this.UpsertPersonalData = this.UpsertPersonalData.bind(this)
            this.UpsertPersonalSetup = this.UpsertPersonalSetup.bind(this)
        }

        /**
         * Delete removes the authenticated user's own profile.
         */
        public async Delete(): Promise<void> {
            await this.baseClient.callTypedAPI("DELETE", `/profiles`)
        }

        /**
         * Get returns the profile for the given user. For the caller's own profile
         * (including when not authenticated), see MyProfile.
         */
        public async Get(): Promise<Profile> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/profiles/profile`)
            return await resp.json() as Profile
        }

        /**
         * GetPersonalData returns the authenticated user's own personal data.
         */
        public async GetPersonalData(): Promise<PersonalData> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/profiles/personal-data`)
            return await resp.json() as PersonalData
        }

        /**
         * GetPersonalSetup returns the caller's setup, defaulting to broadcasting disabled.
         */
        public async GetPersonalSetup(): Promise<PersonalSetup> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/profiles/personal-setup`)
            return await resp.json() as PersonalSetup
        }

        /**
         * GetUserPersonalSetup lets administrators read the selected user's setup.
         */
        public async GetUserPersonalSetup(userID: string): Promise<PersonalSetup> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/profiles/personal-setup/${encodeURIComponent(userID)}`)
            return await resp.json() as PersonalSetup
        }

        /**
         * Login is the public entry point for authenticating a user. It resolves the
         * given email to a user ID via the local profiles database, rejects profiles
         * that are not active, and then asks the auth service to check the password
         * and issue a session, which is returned as an HttpOnly cookie.
         */
        public async Login(params: LoginParams): Promise<LoginResponse> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("POST", `/auth/login`, JSON.stringify(params))
            return await resp.json() as LoginResponse
        }

        /**
         * Me returns the profile of the currently authenticated caller, or nil if
         * the request is not authenticated.
         */
        public async Me(): Promise<Profile> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("GET", `/auth/me`)
            return await resp.json() as Profile
        }

        /**
         * Update replaces the data of the authenticated user's own profile.
         */
        public async Update(params: ProfileParams): Promise<Profile> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("PUT", `/profiles`, JSON.stringify(params))
            return await resp.json() as Profile
        }

        /**
         * UploadAvatar stores the request body as a new avatar image and returns its
         * public URL. The caller is expected to persist the URL via the profile
         * endpoints. Each upload gets a fresh key, so re-uploading never overwrites.
         */
        public async UploadAvatar(method: "POST", body?: RequestInit["body"], options?: CallParameters): Promise<globalThis.Response> {
            return this.baseClient.callAPI(method, `/profiles/avatar`, body, options)
        }

        /**
         * UpsertPersonalData creates or replaces the authenticated user's own personal data.
         */
        public async UpsertPersonalData(params: PersonalDataParams): Promise<PersonalData> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("PUT", `/profiles/personal-data`, JSON.stringify(params))
            return await resp.json() as PersonalData
        }

        /**
         * UpsertPersonalSetup lets administrators assign or revoke a user's broadcasting setup.
         * This stores configuration only; it does not create or delete a LiveKit room.
         */
        public async UpsertPersonalSetup(userID: string, params: PersonalSetupParams): Promise<PersonalSetup> {
            // Now make the actual call to the API
            const resp = await this.baseClient.callTypedAPI("PUT", `/profiles/personal-setup/${encodeURIComponent(userID)}`, JSON.stringify(params))
            return await resp.json() as PersonalSetup
        }
    }
}

